import{_ as a,o as r,c as t,an as o}from"./chunks/framework.-5Uc662M.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/faq.md","filePath":"getting-started/faq.md","lastUpdated":null}'),n={name:"getting-started/faq.md"};function i(s,e,c,d,h,l){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h1><h2 id="Why-is-there-no-renewal-or-AR-constructor?" tabindex="-1">Why is there no renewal or AR constructor? <a class="header-anchor" href="#Why-is-there-no-renewal-or-AR-constructor?" aria-label="Permalink to &quot;Why is there no renewal or AR constructor? {#Why-is-there-no-renewal-or-AR-constructor?}&quot;">​</a></h2><p>The operators describe steps, not models. A renewal process is <a href="/previews/PR286/lib/public#ComposableRecurrences.Recurrence"><code>Recurrence(gi)</code></a> with the reproduction number as its gain, and an AR(p) process is <code>Recurrence(ρ)</code> with the innovations as <code>add</code>. Modelling packages such as <a href="https://composableturingidmodels.epiaware.org" target="_blank" rel="noreferrer">ComposableTuringIDModels.jl</a> name these and give them priors.</p><h2 id="faq-lag-origin" tabindex="-1">Why does a recurrence kernel start at lag 1 and a convolution kernel at lag 0? <a class="header-anchor" href="#faq-lag-origin" aria-label="Permalink to &quot;Why does a recurrence kernel start at lag 1 and a convolution kernel at lag 0? {#faq-lag-origin}&quot;">​</a></h2><p>See <a href="/previews/PR286/explanation/operators#explanation-lag-origin">A recurrence is a convolution of its own outputs</a>.</p><h2 id="How-do-I-get-intermediate-quantities?" tabindex="-1">How do I get intermediate quantities? <a class="header-anchor" href="#How-do-I-get-intermediate-quantities?" aria-label="Permalink to &quot;How do I get intermediate quantities? {#How-do-I-get-intermediate-quantities?}&quot;">​</a></h2><p>Recompute them from the outputs; see <a href="/previews/PR286/explanation/operators#explanation-lag-origin">A recurrence is a convolution of its own outputs</a>.</p><h2 id="faq-backends" tabindex="-1">Which AD backends work? <a class="header-anchor" href="#faq-backends" aria-label="Permalink to &quot;Which AD backends work? {#faq-backends}&quot;">​</a></h2><p>ForwardDiff, Mooncake and Enzyme; see <a href="/previews/PR286/explanation/adjoints-and-backends#adjoint-backends">Backends</a>.</p><h2 id="faq-reactant" tabindex="-1">Does it run under Reactant? <a class="header-anchor" href="#faq-reactant" aria-label="Permalink to &quot;Does it run under Reactant? {#faq-reactant}&quot;">​</a></h2><p>Yes; see the <a href="/previews/PR286/extensions/reactant#extension-reactant">Reactant extension</a>.</p><h2 id="Why-is-my-history-padded-with-zeros?" tabindex="-1">Why is my history padded with zeros? <a class="header-anchor" href="#Why-is-my-history-padded-with-zeros?" aria-label="Permalink to &quot;Why is my history padded with zeros? {#Why-is-my-history-padded-with-zeros?}&quot;">​</a></h2><p>A shorter history means no earlier values; see <code>history</code> in <a href="/previews/PR286/lib/public#ComposableRecurrences.Recurrence"><code>Recurrence</code></a>.</p><h2 id="Recurrence-clashes-with-Lux" tabindex="-1"><code>Recurrence</code> clashes with Lux <a class="header-anchor" href="#Recurrence-clashes-with-Lux" aria-label="Permalink to &quot;`Recurrence` clashes with Lux {#Recurrence-clashes-with-Lux}&quot;">​</a></h2><p>Lux also exports a <code>Recurrence</code>. With both loaded by <code>using</code>, write <a href="/previews/PR286/lib/public#ComposableRecurrences.Recurrence"><code>ComposableRecurrences.Recurrence</code></a> or import the one you need by name.</p>',15)])])}const f=a(n,[["render",i]]);export{p as __pageData,f as default};
